package com.xianshuyuan.scm.order.controller;import com.xianshuyuan.scm.common.api.ApiResponse;import com.xianshuyuan.scm.order.dto.*;import com.xianshuyuan.scm.order.service.*;import com.xianshuyuan.scm.order.vo.OrderReturnResponse;import jakarta.validation.Valid;import java.util.List;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/order-returns") public class OrderReturnController{private final AfterSalesApplicationService app;private final AfterSalesQueryService query;public OrderReturnController(AfterSalesApplicationService a,AfterSalesQueryService q){app=a;query=q;}@PostMapping public ApiResponse<Long> create(@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody OrderReturnCreateRequest r){return ApiResponse.success(app.create(key,r));}@GetMapping("/{id}")public ApiResponse<OrderReturnResponse> get(@PathVariable long id){return ApiResponse.success(query.getReturn(id));}@GetMapping public ApiResponse<List<OrderReturnResponse>> byOrder(@RequestParam long orderId){return ApiResponse.success(query.byOrder(orderId));}@PostMapping("/{id}/approve")public ApiResponse<Long> approve(@RequestHeader("Idempotency-Key")String key,@PathVariable long id,@Valid @RequestBody OrderReturnApproveRequest r){return ApiResponse.success(app.approve(key,id,r));}@PostMapping("/{id}/reject")public ApiResponse<Void> reject(@RequestHeader("Idempotency-Key")String key,@PathVariable long id,@Valid @RequestBody OrderReturnDecisionRequest r){app.reject(key,id,r);return ApiResponse.success(null);}@PostMapping("/{id}/cancel")public ApiResponse<Void> cancel(@RequestHeader("Idempotency-Key")String key,@PathVariable long id,@Valid @RequestBody OrderReturnDecisionRequest r){app.cancel(key,id,r);return ApiResponse.success(null);}}
